// Generated by Trae Work — chart & diagram initialization
// Palette: Business Blue (single active palette for this report)

// ---- Read chart tokens from :root ----
const rootStyle = getComputedStyle(document.documentElement)
const token = (name, fallback) => (rootStyle.getPropertyValue(name) || '').trim() || fallback

const series1 = token('--chart-series-1', '#0969DA')
const series2 = token('--chart-series-2', '#8250DF')
const axisColor = token('--chart-axis', '#656D76')
const labelColor = token('--chart-label', '#656D76')
const gridColor = token('--chart-grid', 'rgba(31, 35, 40, 0.12)')
const tooltipBg = token('--chart-tooltip-bg', '#FFFFFF')
const borderColor = token('--page-border', '#D0D7DE')

// ---- Mermaid: event broadcast flow (Figure 1) ----
if (typeof mermaid !== 'undefined') {
  mermaid.initialize({
    startOnLoad: false,
    theme: 'base',
    securityLevel: 'loose',
    flowchart: { htmlLabels: true, curve: 'basis' },
    themeVariables: {
      primaryColor: '#EAF1FB',
      primaryBorderColor: '#0969DA',
      primaryTextColor: '#1F2328',
      lineColor: '#656D76',
      edgeLabelBackground: '#FFFFFF',
      clusterBkg: '#F6F8FA',
      clusterBorder: '#D0D7DE',
      fontSize: '14px',
    },
  })
  mermaid.run({ querySelector: '.mermaid' }).catch(() => {})
}

// ---- ECharts: fan-out amplification (Figure 2) ----
const chartEl = document.getElementById('fanout-chart')
if (typeof echarts !== 'undefined' && chartEl) {
  const chart = echarts.init(chartEl, null, { renderer: 'svg' })

  const users = ['1 用户', '5 用户', '10 用户', '30 用户']
  // 模型假设：每活跃用户 45 条 Delta + 5 条持久事件/秒；
  // 持久事件经桥接层 emit 两次（原始 + sync 包装），故每人广播量 = 45 + 5×2 = 55 条/秒（评审 R3 修正）
  // v1.2：出口归属过滤（2026-09-05）落地后，网络序列化与写出回落到本人事件量（≈N×55），
  // 仅监听器回调仍按 N² 调用（单次为轻量内存判定）
  const broadcast = [55, 1375, 5500, 49500]
  const filtered = [55, 275, 550, 1650]

  const hasData = broadcast.some((v) => Number.isFinite(v)) || filtered.some((v) => Number.isFinite(v))
  if (!hasData) {
    const empty = document.createElement('div')
    empty.style.cssText = 'display:flex;align-items:center;justify-content:center;height:100%;color:#656D76;font-size:13px;'
    empty.textContent = '暂无数据'
    chartEl.appendChild(empty)
  } else {
    chart.setOption({
      animation: false,
      backgroundColor: 'transparent',
      grid: { left: 72, right: 24, top: 56, bottom: 40 },
      legend: {
        top: 8,
        left: 8,
        itemWidth: 12,
        itemHeight: 8,
        textStyle: { color: labelColor, fontSize: 12 },
        data: ['修复前（v1.1）· 全量广播 N²', '当前（v1.2）· 出口过滤后网络扇出 ≈N'],
      },
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'shadow' },
        appendToBody: true,
        backgroundColor: tooltipBg,
        borderColor: borderColor,
        borderWidth: 1,
        textStyle: { color: '#1F2328', fontSize: 12 },
        valueFormatter: (value) => `${Number(value).toLocaleString()} 次/秒`,
      },
      xAxis: {
        type: 'category',
        data: users,
        axisLine: { lineStyle: { color: axisColor } },
        axisTick: { show: false },
        axisLabel: { color: labelColor, fontSize: 12 },
      },
      yAxis: {
        type: 'value',
        name: '事件分发总次数（次/秒）',
        nameTextStyle: { color: labelColor, fontSize: 11, align: 'left' },
        axisLine: { show: false },
        axisLabel: {
          color: labelColor,
          fontSize: 11,
          formatter: (value) => (value >= 1000 ? `${value / 1000}k` : value),
        },
        splitLine: { lineStyle: { color: gridColor, width: 1 } },
      },
      series: [
        {
          name: '修复前（v1.1）· 全量广播 N²',
          type: 'bar',
          data: broadcast,
          itemStyle: { color: series1, borderRadius: [4, 4, 0, 0] },
          barMaxWidth: 42,
          label: {
            show: true,
            position: 'top',
            color: labelColor,
            fontSize: 11,
            formatter: (p) => p.value.toLocaleString(),
          },
        },
        {
          name: '当前（v1.2）· 出口过滤后网络扇出 ≈N',
          type: 'bar',
          data: filtered,
          itemStyle: { color: series2, borderRadius: [4, 4, 0, 0] },
          barMaxWidth: 42,
          label: {
            show: true,
            position: 'top',
            color: labelColor,
            fontSize: 11,
            formatter: (p) => p.value.toLocaleString(),
          },
        },
      ],
    })
    window.addEventListener('resize', () => chart.resize())
  }
}
